package com.genealogy.source.repository;
import com.baomidou.mybatisplus.core.toolkit.Wrappers; import com.genealogy.source.dto.SourceSearchCriteria; import com.genealogy.source.entity.SourceEntity; import com.genealogy.source.repository.mybatis.*; import com.genealogy.source.repository.query.*; import org.springframework.data.domain.*; import org.springframework.stereotype.Repository; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Repository @Transactional(readOnly=true) public class SourceRepository { private static final int ID_BATCH=500; private final SourcePersistenceMapper persistenceMapper; private final SourceQueryMapper queryMapper; public SourceRepository(SourcePersistenceMapper p,SourceQueryMapper q){persistenceMapper=p;queryMapper=q;} @Transactional public SourceEntity save(SourceEntity e){Objects.requireNonNull(e);if(e.getId()==null)persistenceMapper.insert(e);else if(persistenceMapper.updateAllById(e)!=1)throw new IllegalStateException("Source update expected one row for id "+e.getId());return e;} @Transactional public SourceEntity saveAndFlush(SourceEntity e){return save(e);} @Transactional public List<SourceEntity> saveAll(Iterable<SourceEntity> values){List<SourceEntity> out=new ArrayList<>();if(values!=null)for(SourceEntity e:values)out.add(save(e));return List.copyOf(out);} public Optional<SourceEntity> findById(Long id){return Optional.ofNullable(id==null?null:persistenceMapper.selectById(id));} public List<SourceEntity> findAll(){return persistenceMapper.selectList(Wrappers.<SourceEntity>lambdaQuery().orderByAsc(SourceEntity::getId));} public List<SourceEntity> findAllById(Iterable<Long> ids){LinkedHashSet<Long>s=new LinkedHashSet<>();if(ids!=null)for(Long id:ids)if(id!=null)s.add(id);if(s.isEmpty())return List.of();List<SourceEntity> out=new ArrayList<>();List<Long> v=List.copyOf(s);for(int i=0;i<v.size();i+=ID_BATCH)out.addAll(persistenceMapper.selectBatchIds(v.subList(i,Math.min(i+ID_BATCH,v.size()))));return List.copyOf(out);} @Transactional public void delete(SourceEntity e){Objects.requireNonNull(e);e.requireDraftForDirectDelete();if(e.getId()!=null)persistenceMapper.deleteById(e.getId());} public Page<SourceEntity> findByClanId(Long clanId,Pageable p){long total=persistenceMapper.selectCount(Wrappers.<SourceEntity>lambdaQuery().eq(SourceEntity::getClanId,clanId));if(total==0)return new PageImpl<>(List.of(),p,0);return new PageImpl<>(persistenceMapper.selectList(Wrappers.<SourceEntity>lambdaQuery().eq(SourceEntity::getClanId,clanId).orderByDesc(SourceEntity::getUpdatedAt).orderByDesc(SourceEntity::getId).last("limit "+p.getPageSize()+" offset "+p.getOffset())),p,total);} public Page<SourceEntity> search(Long clanId,SourceSearchCriteria c,int pageNo,int pageSize){String sort=normalizeSort(c.sort());SourceSearchCriteriaRow q=new SourceSearchCriteriaRow(clanId,c.keyword(),c.sourceType(),c.verificationStatus(),c.privacyLevel(),c.targetType(),c.hasAttachment(),c.hasBinding(),sort);long total=queryMapper.count(q);Pageable pageable=PageRequest.of(Math.max(0,pageNo-1),pageSize);return new PageImpl<>(total==0?List.of():queryMapper.search(q,pageable.getOffset(),pageSize),pageable,total);} public long countByClanId(Long clanId){return persistenceMapper.selectCount(Wrappers.<SourceEntity>lambdaQuery().eq(SourceEntity::getClanId,clanId));} public List<Object[]> countDashboardBySourceType(Long clanId){return queryMapper.countDashboardBySourceType(clanId).stream().map(r->new Object[]{r.sourceType(),r.count()}).toList();} public List<SourceEntity> findRecentDashboardSources(Long clanId,Pageable p){return queryMapper.findRecentDashboardSources(clanId,p.getPageSize());} public List<SourceEntity> findTreeSourcesByIds(Long clanId,Collection<Long> ids){return ids==null||ids.isEmpty()?List.of():queryMapper.findTreeSourcesByIds(clanId,ids);} public int countAttachmentsBySourceId(Long sourceId){return queryMapper.countAttachmentsBySourceId(sourceId);} private String normalizeSort(String s){if(s==null||s.isBlank())return "updatedAt,desc";String[]p=s.split(",",2);Set<String>f=Set.of("id","sourceName","sourceType","verificationStatus","privacyLevel","createdAt","updatedAt");String field=f.contains(p[0])?p[0]:"updatedAt";String dir=p.length>1&&"asc".equalsIgnoreCase(p[1])?"asc":"desc";return field+","+dir;} }
